func fzMix(h int32, v int32) int32 {
	// A rolling 23-bit hash step; any I32 v.
	return ((h * 131) + (v & 8388607)) % 8388593
}

func fzGeometry(pg *port.Cells) int32 {
	var n int32 = pdfdoc.PdPgCount(pg)
	var i int32 = 0
	var k int32 = 0
	var h int32 = 7
	for i < n {
		k = 0
		for k < 4 {
			h = fzMix(h, pdfdoc.PdPgMedia(pg, i, k))
			h = fzMix(h, pdfdoc.PdPgCrop(pg, i, k))
			k += 1
		}
		h = fzMix(h, pdfdoc.PdPgRotate(pg, i))
		i += 1
	}
	return h
}

func fzFont(src *port.Src, ar *port.Cells, dc *port.Cells, a *port.Cells, b *port.Cells, st *port.Cells, f *port.Cells, out *port.Cells, h int32, h0 int32) int32 {
	// Load dictionary h as a font, and fold in what it says about every
	// one-byte code. Answers the new hash.
	var s int32 = pdffont.PfnLoad(src, ar, dc, a, b, st, f, out, h)
	var acc int32 = fzMix(h0, s)
	var code int32 = 0
	var n int32 = 0
	var j int32 = 0
	acc = fzMix(acc, pdffont.PfnWarn(f))
	if s == 0 {
		acc = fzMix(acc, pdffont.PfnKindOf(f))
		if pdffont.PfnKindOf(f) != 0 {
			for code < 256 {
				n = pdffont.PfnMap(f, code)
				acc = fzMix(acc, n)
				acc = fzMix(acc, pdffont.PfnHowOf(f))
				j = 0
				for (j < n) && (j < 4) {
					acc = fzMix(acc, pdffont.PfnCp(f, j))
					j += 1
				}
				acc = fzMix(acc, pdffont.PfnWidth(f, code))
				code += 1
			}
		}
	}
	return acc
}

